        if (!q('.rmd-nm-fase')) { toast(`Elige la fase de esta versión${g.__rmdFaseAnt ? ` (la ${g.__rmdFaseAnt})` : ''}: no siempre es la misma que la anterior.`, true); g.querySelector('.rmd-nm-fase').focus(); return; }
