      const conAvisos = new Map();
      if (porPaso) porPaso.forEach((l, paso) => { const mal = l.map((q) => ({ ...q, avisos: avisosDePM(q) })).filter((q) => q.avisos.length); if (mal.length) conAvisos.set(paso, mal); });
