        doc.open = function (opciones) { usada = true; est.abiertos++; return abrir.length > 1 ? abrir.call(doc, opciones || {}, w) : abrir.call(doc, w); };   // 0.1: open(opciones, ventana); 0.2: open(ventana)
        return doc;
