      if (cols.length) { colsOrden.forEach((p, k) => h.poner({ c: c0 + R + k, r: rEnc }, valorCampo(cols[0], p))); h.poner({ c: c0 + R + colsOrden.length, r: rEnc }, 'Total general'); }
