      const hojas = []; for (const m of wb.matchAll(/<sheet\b[^>]*>/g)) { const nom = /\bname="([^"]*)"/.exec(m[0]), rid = /\br:id="([^"]+)"/.exec(m[0]); if (nom && rid) hojas.push({ nombre: desX(nom[1]), ruta: 'xl/' + destino[rid[1]].replace(/^\/?xl\//, '').replace(/^\//, '') }); }
