          const enSeccion = a.seccion ? en.filter((x) => plano(x.lista).includes(a.seccion)) : en, donde = enSeccion.length ? enSeccion : en;
          const faltan = Object.keys(CASILLAS).filter((c) => p[c] && !donde.some((x) => x[c === 'rPor' ? 'rpor' : c]));
