        const M = t.pm ? PM : P, porCodigo = () => { const c = [...M.values()].filter((x) => x.codigo === t.valor); return c.length === 1 ? c[0] : null; };
        const f = (t.id && M.get(t.id)) || (info ? porCodigo() : null), av = [];
