    if (!tabla || !on('revisor') || typeof sap === 'undefined') { document.querySelectorAll('.rmd-revisor').forEach((e) => e.remove()); document.querySelectorAll('.rmd-con-revisor').forEach((e) => e.classList.remove('rmd-con-revisor')); return; }
