        const nuevas = rutas.map((q) => datos[+String(q).split('/')[1]]).filter(Boolean);
        const ya = (((ctrl.getView().getModel('listMdReceta') || { getData: () => [] }).getData()) || []).filter((r) => r.activo !== false && r.recetaId).map((r) => r.recetaId);
