  const ICONO_CAMBIAR = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2.5 5h10M10 2.5 12.5 5 10 7.5"/><path d="M13.5 11h-10M6 8.5 3.5 11 6 13.5"/></svg>';
