      const f = []; let c = 0; [...row.getElementsByTagName('Cell')].forEach((cell) => { const i = +(cell.getAttribute('ss:Index') || 0); if (i) c = i - 1; const dt = cell.getElementsByTagName('Data')[0]; f[c] = dt ? dt.textContent : ''; c++; });
