    if (hoy) CAMPOS_RUTA.forEach(([k, nombre, f, avisa]) => { if (!avisa) return; const a = f(rc[k]), s = f(hoy[k]); if (a !== s) cambios.push({ campo: nombre, asociada: a, sap: s, anterior: null, clave: k, avisa: true }); });
